/**
 * Suggestion Panel Component
 *
 * Displays auto-optimization suggestions generated by the AI
 * optimization engine.  Suggestions are dynamic text recommendations
 * for improving furnace combustion efficiency.
 *
 * Features:
 * - SVG lightbulb icon in the section header
 * - Glass-morphism content card with blue info accent
 * - Proper typography with line height and spacing
 * - AI engine attribution footer
 */

import { useFurnaceStore } from "../state/FurnaceStore";
import { panelStyles as S } from "./panelStyles";

// ============================================================================
// SVG ICONS
// ============================================================================

const IconLightbulb = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M12 2C8.13 2 5 5.13 5 9C5 12.38 9.06 17.31 11.17 19.67C11.65 20.19 12.35 20.19 12.83 19.67C14.94 17.31 19 12.38 19 9C19 5.13 15.87 2 12 2Z" strokeWidth="1.5" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9 21C9 21.55 9.45 22 10 22H14C14.55 22 15 21.55 15 21" strokeWidth="1.5" stroke="currentColor" strokeLinecap="round"/>
    <path d="M9.5 9C9.5 7.62 10.62 6.5 12 6.5C13.38 6.5 14.5 7.62 14.5 9C14.5 9.79 14.02 10.49 13.32 10.82C12.79 11.07 12.5 11.57 12.5 12.16V13" strokeWidth="1.5" stroke="currentColor" strokeLinecap="round"/>
    <circle cx="12" cy="15" r="1" strokeWidth="1.5" stroke="currentColor"/>
  </svg>
);

const IconSparkles = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M12 2L13.5 8.5H20L13 12.5L15.5 19L12 15.5L8.5 19L11 12.5L4 8.5H10.5L12 2Z" strokeWidth="1.5" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export default function SuggestionPanel() {
  const { state } = useFurnaceStore();
  if (!state.suggestion) return null;

  return (
    <div style={S.section}>
      {/* ── Header with icon ── */}
      <div style={{ ...S.sectionLabel, gap: "6px" }}>
        <span style={{ display: "flex", alignItems: "center", opacity: 0.7 }}><IconLightbulb /></span>
        AUTO-OPTIMIZATION SUGGESTION
      </div>

      {/* ── Suggestion Content Card ── */}
      <div style={styles.suggestionCard}>
        <div style={styles.suggestionContent}>
          {state.suggestion}
        </div>
        <div style={styles.suggestionFooter}>
          <span style={styles.suggestionAttribution}>
            <span style={{ display: "flex", alignItems: "center", gap: "4px", opacity: 0.6 }}><IconSparkles /></span>
            AI Optimization Engine
          </span>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// STYLES
// ============================================================================

const styles = {
  // ── Suggestion Content Card ──
  suggestionCard: {
    background: "linear-gradient(135deg, rgba(30, 41, 59, 0.5) 0%, rgba(15, 23, 45, 0.6) 100%)",
    borderRadius: "10px",
    border: "1px solid rgba(59, 130, 246, 0.2)",
    borderLeft: "3px solid rgba(59, 130, 246, 0.5)",
    backdropFilter: "blur(12px) saturate(160%)",
    boxShadow: "0 4px 20px rgba(0, 0, 0, 0.15)",
    padding: "14px",
    overflow: "hidden",
  },

  // ── Suggestion Text ──
  suggestionContent: {
    fontFamily: "'Inter', sans-serif",
    fontSize: "12px",
    lineHeight: 1.6,
    color: "rgba(200, 220, 255, 0.8)",
    fontWeight: 400,
    marginBottom: "10px",
  },

  // ── Suggestion Footer ──
  suggestionFooter: {
    display: "flex",
    justifyContent: "flex-end",
    alignItems: "center",
  },

  // ── Attribution ──
  suggestionAttribution: {
    display: "inline-flex",
    alignItems: "center",
    gap: "4px",
    fontFamily: "'Inter', sans-serif",
    fontSize: "9px",
    fontWeight: 700,
    letterSpacing: "0.08em",
    color: "rgba(165, 180, 255, 0.5)",
    textTransform: "uppercase",
  },
};
